/**
 * jun-26 otel-trace-sink receiver (ADR-0268).
 *
 * `src/apps/bench/otel-trace-sink.ts` is the operator-side OTLP/JSON receiver that prints
 * the bench agent's live spans. This test pins that its parser consumes the EXACT
 * wire shape `src/observability/otel-exporter.ts` emits — generated by driving the
 * REAL exporter (`otelHttpExporter` + `buildExportingTracer`) through a fake fetch,
 * capturing the POST body verbatim, and feeding it to `parseResourceSpans` /
 * `parseResourceMetrics`. If the exporter's serializer drifts, this test breaks
 * (no hand-rolled fixture to rot independently).
 *
 * Asserts the receiver extracts: span name, duration (from string-nanos
 * start/end), status, kind, and key attrs (gen_ai.* / tool / instance); and a
 * metric's name + value + attrs.
 */
import { describe, expect, test } from "bun:test"
import {
  buildExportingTracer,
  exporterMetricSink,
  otelHttpExporter,
} from "@/observability/otel-exporter"
import {
  formatMetricLine,
  formatSpanLine,
  parseResourceMetrics,
  parseResourceSpans,
  parseResourceSpansFull,
} from "../../src/apps/bench/otel-trace-sink"

const ENDPOINT = "http://127.0.0.1:4318"

interface Captured {
  readonly path: string
  readonly body: unknown
}
const makeFakeFetch = (): { fetch: typeof fetch; calls: Captured[] } => {
  const calls: Captured[] = []
  const f = async (input: unknown, init?: RequestInit): Promise<Response> => {
    const url = typeof input === "string" ? input : String(input)
    calls.push({
      path: url.replace(ENDPOINT, ""),
      body: typeof init?.body === "string" ? JSON.parse(init.body) : undefined,
    })
    // biome-ignore lint/suspicious/noExplicitAny: minimal fake Response
    return { ok: true, status: 200 } as any
  }
  return { fetch: f as unknown as typeof fetch, calls }
}

const noTimer = {
  setIntervalImpl: () => Symbol("noop") as unknown,
  clearIntervalImpl: () => {},
}

describe("otel-trace-sink parses the exporter's exact OTLP/JSON shape", () => {
  test("a real exported span round-trips: name + duration + status + key attrs", async () => {
    const { fetch, calls } = makeFakeFetch()
    let clock = 1_000
    const exporter = otelHttpExporter({
      endpoint: ENDPOINT,
      fetch,
      flushIntervalMs: 0,
      now: () => clock,
      ...noTimer,
    })
    const tracer = buildExportingTracer(exporter, { now: () => clock })

    const span = tracer.startSpan("handle_tool_call", {
      kind: "client",
      attributes: { "quanta.tool.name": "bash", "quanta.instance.id": "django__django-11138" },
    })
    span.setAttribute("gen_ai.request.model", "gpt-5")
    clock = 1_250 // 250ms elapsed
    span.setStatus("ok")
    span.end()
    await exporter.flush()

    const traceCall = calls.find((c) => c.path === "/v1/traces")
    expect(traceCall).toBeDefined()

    const parsed = parseResourceSpans(traceCall?.body as never)
    expect(parsed.length).toBe(1)
    const s = parsed[0]
    expect(s?.name).toBe("handle_tool_call")
    expect(s?.durationMs).toBe(250)
    expect(s?.status).toBe("ok")
    expect(s?.kind).toBe("client")
    expect(s?.attrs["quanta.tool.name"]).toBe("bash")
    expect(s?.attrs["quanta.instance.id"]).toBe("django__django-11138")
    expect(s?.attrs["gen_ai.request.model"]).toBe("gpt-5")

    // The one-line render surfaces the high-signal keys.
    const line = formatSpanLine(s as never)
    expect(line).toContain("handle_tool_call")
    expect(line).toContain("250ms")
    expect(line).toContain("quanta.tool.name=bash")
    expect(line).toContain("gen_ai.request.model=gpt-5")
  })

  test("an error span renders with the error mark", async () => {
    const { fetch, calls } = makeFakeFetch()
    const clock = 5_000
    const exporter = otelHttpExporter({
      endpoint: ENDPOINT,
      fetch,
      flushIntervalMs: 0,
      now: () => clock,
      ...noTimer,
    })
    const tracer = buildExportingTracer(exporter, { now: () => clock })
    const span = tracer.startSpan("run_sampling_request")
    span.setStatus("error", "boom")
    span.end()
    await exporter.flush()

    const parsed = parseResourceSpans(
      (calls.find((c) => c.path === "/v1/traces")?.body ?? {}) as never,
    )
    expect(parsed[0]?.status).toBe("error")
    expect(parsed[0]?.statusMessage).toBe("boom")
    const line = formatSpanLine(parsed[0] as never)
    expect(line).toContain("✗")
    expect(line).toContain("boom") // the message is inline, not just the mark
  })

  test("a real exported metric round-trips: name + value + attrs", async () => {
    const { fetch, calls } = makeFakeFetch()
    const exporter = otelHttpExporter({
      endpoint: ENDPOINT,
      fetch,
      flushIntervalMs: 0,
      ...noTimer,
    })
    const sink = exporterMetricSink(exporter)
    sink.send({
      name: "quanta.tool.invocations.total",
      kind: "counter",
      value: 3,
      labels: { tool: "bash" },
      at: 1_700_000_000_000,
    })
    await exporter.flush()

    const metricCall = calls.find((c) => c.path === "/v1/metrics")
    expect(metricCall).toBeDefined()
    const parsed = parseResourceMetrics(metricCall?.body as never)
    expect(parsed.length).toBe(1)
    expect(parsed[0]?.name).toBe("quanta.tool.invocations.total")
    expect(parsed[0]?.value).toBe(3)
    expect(parsed[0]?.attrs.tool).toBe("bash")
    expect(formatMetricLine(parsed[0] as never)).toContain("quanta.tool.invocations.total = 3")
  })

  test("malformed / empty envelope ⇒ no throw, empty result (receiver never crashes)", () => {
    expect(parseResourceSpans({} as never)).toEqual([])
    expect(parseResourceSpans({ resourceSpans: [{}] } as never)).toEqual([])
    expect(parseResourceMetrics({} as never)).toEqual([])
    expect(parseResourceSpansFull({} as never)).toEqual([])
    expect(parseResourceSpansFull({ resourceSpans: [{}] } as never)).toEqual([])
  })

  // The waterfall UI (src/apps/bench/trace-viewer.html) lays spans out on a timeline and
  // nests them by parent — so the receiver's STRUCTURAL parser must preserve the
  // trace/span ids and the nanosecond start/end that formatSpanLine throws away.
  test("parseResourceSpansFull preserves trace/span ids + nanosecond timestamps for the waterfall", async () => {
    const { fetch, calls } = makeFakeFetch()
    let clock = 2_000
    const exporter = otelHttpExporter({
      endpoint: ENDPOINT,
      fetch,
      flushIntervalMs: 0,
      now: () => clock,
      ...noTimer,
    })
    const tracer = buildExportingTracer(exporter, { now: () => clock })
    const span = tracer.startSpan("run_sampling_request", {
      attributes: { "gen_ai.response.model": "gpt-5.5" },
    })
    clock = 2_400 // 400ms elapsed
    span.setStatus("ok")
    span.end()
    await exporter.flush()

    const body = calls.find((c) => c.path === "/v1/traces")?.body
    const full = parseResourceSpansFull(body as never)
    expect(full.length).toBe(1)
    const s = full[0]
    // ids present + non-empty so the browser can group-by-trace and nest.
    expect(s?.traceId).toBeTruthy()
    expect(s?.spanId).toBeTruthy()
    // a root span has no parent — the field exists (string), never undefined.
    expect(typeof s?.parentSpanId).toBe("string")
    // nanosecond timeline inputs survive as finite numbers, end > start.
    expect(Number.isFinite(s?.startNano)).toBe(true)
    expect(Number.isFinite(s?.endNano)).toBe(true)
    expect((s?.endNano ?? 0) > (s?.startNano ?? 0)).toBe(true)
    expect(s?.durationMs).toBe(400)
    expect(s?.attrs["gen_ai.response.model"]).toBe("gpt-5.5")
  })

  // jun-27: error spans carried `status: error` but DROPPED the message — the
  // operator saw THAT a tool call failed, never WHAT (ENOENT? timeout? 429?),
  // forcing an SSH into the box to diagnose. The receiver must surface the
  // exported `status.message` so the live UI / span feed alone is diagnosable.
  test("parseResourceSpansFull surfaces the error status MESSAGE (WHAT failed, not just that it did)", async () => {
    const { fetch, calls } = makeFakeFetch()
    const exporter = otelHttpExporter({
      endpoint: ENDPOINT,
      fetch,
      flushIntervalMs: 0,
      ...noTimer,
    })
    const tracer = buildExportingTracer(exporter, { now: () => 1_000 })
    const span = tracer.startSpan("handle_tool_call")
    span.setStatus("error", "ENOENT: reproduce_issue.py not found")
    span.end()
    await exporter.flush()

    const full = parseResourceSpansFull(
      (calls.find((c) => c.path === "/v1/traces")?.body ?? {}) as never,
    )
    expect(full[0]?.status).toBe("error")
    expect(full[0]?.statusMessage).toBe("ENOENT: reproduce_issue.py not found")
    // an OK span carries no status message (only meaningful for errors)
    const { calls: okCalls } = (() => {
      const f = makeFakeFetch()
      const ex = otelHttpExporter({
        endpoint: ENDPOINT,
        fetch: f.fetch,
        flushIntervalMs: 0,
        ...noTimer,
      })
      const t = buildExportingTracer(ex, { now: () => 1_000 })
      const sp = t.startSpan("ok_span")
      sp.setStatus("ok")
      sp.end()
      void ex.flush()
      return f
    })()
    const okFull = parseResourceSpansFull(
      (okCalls.find((c) => c.path === "/v1/traces")?.body ?? {}) as never,
    )
    expect(okFull[0]?.statusMessage).toBeUndefined()
  })
})
